// Build-time only. The deployed extension imports the committed, standalone bundle.
import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

process.chdir(fileURLToPath(new URL(".", import.meta.url)));
await build({
  stdin: { contents: 'export { Parser } from "htmlparser2";', resolveDir: process.cwd() },
  bundle: true,
  format: "esm",
  platform: "node",
  target: "node24",
  minify: true,
  outfile: "htmlparser2.mjs",
  banner: { js: "// Generated by npm ci && npm run build in vendor/. See THIRD-PARTY-LICENSES.txt." },
});

// Include notices for the parser and its complete dependency set, even modules
// removed by tree shaking. esbuild is only a build tool, never shipped in the bundle.
const notices = [];
for (const name of ["htmlparser2", "entities", "domhandler", "domutils", "domelementtype"]) {
  const root = `node_modules/${name}`;
  const { version } = JSON.parse(await readFile(`${root}/package.json`, "utf8"));
  const license = (await readFile(`${root}/LICENSE`, "utf8")).replace(/[\t ]+$/gm, "");
  notices.push(`${name}@${version}\n\n${license}`);
}
await writeFile("THIRD-PARTY-LICENSES.txt", notices.join("\n\n---\n\n"));